selector_to_html = {"a[href=\"#c\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.3.1 \u5e26 C++ \u6269\u5c55\u7279\u6027\u7684\u5b89\u88c5<a class=\"headerlink\" href=\"#c\" title=\"Link to this heading\">#</a></h3><p>\u5982\u679c\u4f60\u4e0d\u6253\u7b97\u542f\u7528 C++ \u5c01\u88c5\u7684\u7b97\u5b50\uff0c\u53ef\u4ee5\u8df3\u8fc7\u8fd9\u4e00\u6b65\u3002</p><p>\u5982\u8981\u6784\u5efa\u3001\u5b89\u88c5 <em>FlagGems</em> \u4e2d\u7684 C++ \u6269\u5c55\u7279\u6027\uff0c\u5219\u5fc5\u987b\u5728\u5b89\u88c5\u8fc7\u7a0b\u4e2d\u4e3a CMake\n\u6307\u5b9a\u9009\u9879 <code class=\"docutils literal notranslate\"><span class=\"pre\">-DFLAGGEMS_BUILD_C_EXTENSION=ON</span></code>\u3002\u4f60\u53ef\u4ee5\u901a\u8fc7\u8bbe\u7f6e <code class=\"docutils literal notranslate\"><span class=\"pre\">SKBUILD_CMAKE_ARGS</span></code>\n\u6216\u8005 <code class=\"docutils literal notranslate\"><span class=\"pre\">CMAKE_ARGS</span></code> \u73af\u5883\u53d8\u91cf\u8fd9\u4e24\u79cd\u65b9\u5f0f\u6765\u4e3a CMake \u63d0\u4f9b\u53c2\u6570\u3002\n\u4e0b\u9762\u7684\u547d\u4ee4\u4ee5\u53ef\u7f16\u8f91\u6a21\u5f0f\uff08Editable Mode\uff09\u5b89\u88c5 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> \u5305\uff0c\u540c\u65f6\u4f7f\u7528\n<code class=\"docutils literal notranslate\"><span class=\"pre\">CMAKE_ARGS</span></code> \u73af\u5883\u53d8\u91cf\u6765\u542f\u7528 C++ \u6269\u5c55\u7279\u6027\uff1a</p>", "a[href=\"#python\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">3.3.2 \u4ec5\u5b89\u88c5 Python \u8f6f\u4ef6\u5305<a class=\"headerlink\" href=\"#python\" title=\"Link to this heading\">#</a></h4><p>\u4f60\u53ef\u4ee5\u5c06 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> \u4f5c\u4e3a\u7eaf Python \u8f6f\u4ef6\u5305\u6765\u5b89\u88c5\u3002\n\u5982\u679c\u4f60\u5e0c\u671b\u76f4\u63a5\u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code>\uff0c\u65e0\u610f\u5bf9\u5176\u5b9e\u73b0\u4f5c\u4efb\u4f55\u4fee\u6539\u6216\u5b9a\u5236\uff0c\n\u53ef\u4ee5\u5c06\u5176\u5b89\u88c5\u5230\u4f60\u7684 Python \u8fd0\u884c\u73af\u5883\u4e2d\uff1a</p>", "a[href=\"#libtriton-jit-libtriton-jit\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.5 \u5173\u4e8e <code class=\"docutils literal notranslate\"><span class=\"pre\">libtriton_jit</span></code> \u5e93   {#libtriton-jit}<a class=\"headerlink\" href=\"#libtriton-jit-libtriton-jit\" title=\"Link to this heading\">#</a></h3><p><em>FlagGems</em> \u7684 C++ \u6269\u5c55\u7279\u6027\u4f9d\u8d56\u4e8e <a class=\"reference external\" href=\"https://github.com/flagos-ai/libtriton_jit/\">TritonJIT</a>\uff0c\n\u4e00\u4e2a\u7528 C++ \u6765\u5b9e\u73b0 Triton JIT \u8fd0\u884c\u65f6\u7684\u5e93\u3002\u5229\u7528 TritonJIT\uff0c\u6211\u4eec\u53ef\u4ee5\u5728 C++\n\u4ee3\u7801\u4e2d\u8c03\u7528 Triton \u7684 JIT \u51fd\u6570\u3002\n\u5982\u679c\u5728\u6784\u5efa\u3001\u5b89\u88c5 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> \u65f6\u4f7f\u7528\u5916\u90e8\u7684 TritonJIT \u5e93\uff0c\n\u5c31\u610f\u5473\u7740\u4f60\u9700\u8981\u5355\u72ec\u6784\u5efa\u5e76\u5b89\u88c5\u5b83\uff0c\u4ece\u800c\u6ee1\u8db3 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> CMake \u6784\u5efa\u7684\u524d\u63d0\u6761\u4ef6\uff1b\n\u4e4b\u540e\u8981\u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">-DTritonJIT_ROOT=&lt;\u5b89\u88c5\u8def\u5f84&gt;</span></code> \u9009\u9879\u5c06\u5b89\u88c5\u4f4d\u7f6e\u544a\u77e5 CMake\u3002</p><p>\u4f8b\u5982\uff0c\u4e0b\u9762\u7684\u547d\u4ee4\u4f1a\u542f\u52a8\u4e00\u4e2a\u53ef\u7f16\u8f91\u7684\u5b89\u88c5\u52a8\u4f5c\uff0c\n\u5e76\u4e14\u4f7f\u7528\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">/usr/local/lib/libtriton_jit</span></code> \u4e0b\u5df2\u7ecf\u5b89\u88c5\u597d\u7684\u5916\u90e8 <em>TritonJIT</em> \u5b9e\u4f8b\u3002</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. \u73af\u5883\u51c6\u5907<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2>", "a[href=\"../usage/non-nvidia.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5728\u975e\u82f1\u4f1f\u8fbe\uff08NVIDIA\uff09\u786c\u4ef6\u4e0a\u4f7f\u7528 FlagGems<a class=\"headerlink\" href=\"#nvidia-flaggems\" title=\"Link to this heading\">#</a></h1><h2>1. \u652f\u6301\u7684\u5e73\u53f0<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> \u5728 NVIDIA \u82af\u7247\u4e4b\u5916\u652f\u6301\u82e5\u5e72\u4e0d\u540c\u7c7b\u578b\u7684 AI \u82af\u7247\u6216\u5e73\u53f0\u3002\n\u8bf7\u53c2\u9605<a class=\"reference internal\" href=\"../overview/platforms.html\"><span class=\"doc std std-doc\">\u5e73\u53f0\u652f\u6301</span></a>\n\u6587\u6863\u4e86\u89e3\u5df2\u7ecf\u9a8c\u8bc1\u8fc7\u7684\u5e73\u53f0\u7684\u6700\u65b0\u5217\u8868\u3002</p>", "a[href=\"#install-from-source\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. \u4ece\u6e90\u7801\u6784\u5efa\u3001\u5b89\u88c5 {#install-from-source}<a class=\"headerlink\" href=\"#install-from-source\" title=\"Link to this heading\">#</a></h2><p>\u4e0e\u5f88\u591a\u5176\u4ed6\u5f00\u6e90\u8f6f\u4ef6\u7c7b\u4f3c\uff0c<em>FlagGems</em> \u652f\u6301\u4ece\u6e90\u7801\u6784\u5efa\u3001\u5b89\u88c5\u3002</p>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.1 \u514b\u9686\u6e90\u4ee3\u7801<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#id3\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.3 \u5b89\u88c5\u8f6f\u4ef6\u5305<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h3><p><em>FlagGems</em> \u65e2\u53ef\u4ee5\u4f5c\u4e3a\u7eaf Python \u8f6f\u4ef6\u5305\u6765\u5b89\u88c5\uff0c\u4e5f\u652f\u6301\u5e26 C++ \u6269\u5c55\u7279\u6027\u7684\u5b89\u88c5\u3002\nC++ \u6269\u5c55\u7279\u6027\u4ecd\u7136\u662f\u4e00\u79cd\u5b9e\u9a8c\u6027\u7279\u6027\uff0c\u6240\u4ee5\u5982\u679c\u4f60\u8ba1\u5212\u5728\u751f\u4ea7\u73af\u5883\u4e2d\u4f7f\u7528\uff0c\n\u8bf7\u786e\u4fdd\u5728\u5f00\u59cb\u4f7f\u7528\u4e4b\u524d\u8fdb\u884c\u5fc5\u8981\u7684\u8bc4\u4f30\u6d4b\u8bd5\u3002</p>", "a[href=\"#pip-pip-options\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.1 \u5e38\u7528\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span></code> \u9009\u9879 {#pip-options}<a class=\"headerlink\" href=\"#pip-pip-options\" title=\"Link to this heading\">#</a></h3><p>\u4e00\u4e9b\u7ecf\u5e38\u4f7f\u7528\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span></code> \u547d\u4ee4\u884c\u9009\u9879\u5305\u62ec\uff1a</p>", "a[href=\"#flagtree\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.2 \u5b89\u88c5 FlagTree<a class=\"headerlink\" href=\"#flagtree\" title=\"Link to this heading\">#</a></h3><p>\u5982\u679c\u4f60\u5e0c\u671b\u4f7f\u7528\u539f\u751f\u7684 Triton \u7f16\u8bd1\u5668\u800c\u4e0d\u662f <em>FlagTree</em>\uff0c\u53ef\u4ee5\u8df3\u8fc7\u8fd9\u4e00\u6b65\u3002</p><p><a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree\">FlagTree</a> \u662f\u4e00\u4e2a\u9488\u5bf9\u591a\u79cd\nAI \u5e73\u53f0\u7684\u3001\u5f00\u6e90\u7684\u7edf\u4e00\u7f16\u8bd1\u5668\u3002\u5728\u5b89\u88c5 FlagTree \u4e4b\u524d\uff0c\u8bf7\u5148\u9605\u8bfb FlagTree\n\u9879\u76ee\u7684\u8fd0\u884c\u73af\u5883\u9700\u6c42\u3002</p>", "a[href=\"#pypi\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. \u4ece PyPI \u5b89\u88c5<a class=\"headerlink\" href=\"#pypi\" title=\"Link to this heading\">#</a></h2><p>\u4f60\u53ef\u4ee5\u4f7f\u7528\u81ea\u5df1\u5e38\u7528\u7684 Python \u5305\u7ba1\u7406\u5668\uff08\u4f8b\u5982 <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span></code>\uff09\u4ece <a class=\"reference external\" href=\"https://pypi.org/project/flag-gems/\">PyPI</a>\n\u5b89\u88c5 <em>FlagGem</em> \u7684\u8f6f\u4ef6\u5305\uff1a</p>", "a[href=\"#flaggems\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b89\u88c5 FlagGems<a class=\"headerlink\" href=\"#flaggems\" title=\"Link to this heading\">#</a></h1><h2>1. \u73af\u5883\u51c6\u5907<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#scikit-build-core-scikit-build-core-options\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.4 <code class=\"docutils literal notranslate\"><span class=\"pre\">scikit-build-core</span></code> \u9009\u9879  {#scikit-build-core-options}<a class=\"headerlink\" href=\"#scikit-build-core-scikit-build-core-options\" title=\"Link to this heading\">#</a></h3><p>\u5de5\u5177 <code class=\"docutils literal notranslate\"><span class=\"pre\">scikit-build-core</span></code> \u662f\u4e00\u4e2a<strong>\u6784\u5efa\u540e\u7aef\uff08Build Backend\uff09</strong>\uff0c\u7528\u6765\u6865\u63a5 CMake\n\u548c Python \u8fd9\u4e24\u4e2a\u6784\u5efa\u7cfb\u7edf\uff0c\u8fdb\u800c\u7b80\u5316\u4f7f\u7528 CMake \u6765\u6784\u5efa Python \u6a21\u5757\u7684\u8fc7\u7a0b\u3002\n\u7528\u6765\u914d\u7f6e <code class=\"docutils literal notranslate\"><span class=\"pre\">scikit-build-core</span></code> \u7684\u4e00\u4e9b\u5e38\u7528\u73af\u5883\u53d8\u91cf\u5305\u62ec\uff1a</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. \u53c2\u8003\u8d44\u6599<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><h3>4.1 \u5e38\u7528\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span></code> \u9009\u9879 {#pip-options}<a class=\"headerlink\" href=\"#pip-pip-options\" title=\"Link to this heading\">#</a></h3><p>\u4e00\u4e9b\u7ecf\u5e38\u4f7f\u7528\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span></code> \u547d\u4ee4\u884c\u9009\u9879\u5305\u62ec\uff1a</p>", "a[href=\"#cmake-cmake-options\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.3 \u5173\u4e8e CMake \u9009\u9879 {#cmake-options}<a class=\"headerlink\" href=\"#cmake-cmake-options\" title=\"Link to this heading\">#</a></h3><p>\u5982\u524d\u6240\u8ff0\uff0c\u5728\u6784\u5efa\u3001\u5b89\u88c5 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> \u65f6\uff0c\u4f60\u53ef\u4ee5\u901a\u8fc7\u73af\u5883\u53d8\u91cf <code class=\"docutils literal notranslate\"><span class=\"pre\">SKBUILD_CMAKE_ARGS</span></code>\n\u6216 <code class=\"docutils literal notranslate\"><span class=\"pre\">CMAKE_ARGS</span></code> \u5411 CMake \u4f20\u9012\u53c2\u6570\u9009\u9879\u3002\n\u9700\u8981\u6ce8\u610f\u7684\u662f\uff0c\u5bf9\u4e8e\u73af\u5883\u53d8\u91cf <code class=\"docutils literal notranslate\"><span class=\"pre\">SKBUILD_CMAKE_ARGS</span></code> \u800c\u8a00\uff0c\u5982\u679c\u9700\u8981\u6307\u5b9a\u591a\u4e2a\u53c2\u6570\u9009\u9879\uff0c\n\u8fd9\u4e9b\u53c2\u6570\u8981\u4f7f\u7528\u5206\u53f7\uff08<code class=\"docutils literal notranslate\"><span class=\"pre\">:</span></code>\uff09\u9694\u5f00\uff1b\u5bf9\u4e8e <code class=\"docutils literal notranslate\"><span class=\"pre\">CMAKE_ARGS</span></code>\uff0c\u591a\u4e2a\u9009\u9879\u8981\u4f7f\u7528\u7a7a\u683c\u6765\u5206\u9694\u3002\n\u9020\u6210\u8fd9\u4e00\u5dee\u522b\u7684\u4e3b\u8981\u539f\u56e0\u662f <code class=\"docutils literal notranslate\"><span class=\"pre\">scikit-build-core</span></code> \u4e0e\u5176\u524d\u8eab <code class=\"docutils literal notranslate\"><span class=\"pre\">scikit-build</span></code>\n\u4e4b\u95f4\u5b58\u5728\u4e0d\u517c\u5bb9\u7684\u53d8\u66f4\u3002</p><p>\u7528\u6765\u914d\u7f6e <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> \u5b89\u88c5\u7684 CMake \u9009\u9879\u5982\u4e0b\uff1a</p>", "a[href=\"#build-isolation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4.2 \u5173\u4e8e\u6784\u5efa\u9694\u79bb {#build-isolation}<a class=\"headerlink\" href=\"#build-isolation\" title=\"Link to this heading\">#</a></h3><p>\u6839\u636e\u793e\u533a <a class=\"reference external\" href=\"https://peps.python.org/pep-0517/#recommendations-for-build-frontends-non-normative\">PEP 517</a> \u6240\u7ed9\u7684\u5021\u8bae\uff0c\n\u8bf8\u5982 <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span></code> \u6216\u8005\u5176\u4ed6\u4e00\u4e9b\u8f83\u65b0\u7684\u6784\u5efa\u524d\u7aef\uff08build frontend\uff09\u4e00\u822c\u4f1a\u4f7f\u7528\u9694\u79bb\u73af\u5883\u6765\u6784\u5efa\u8f6f\u4ef6\u5305\u3002\n\u6784\u5efa\u8fc7\u7a0b\u4f1a\u521b\u5efa\u4e00\u4e2a<strong>\u865a\u62df\u73af\u5883\uff08Virtual Environment\uff09</strong>\uff0c\u5e76\u5728\u8be5\u73af\u5883\u4e2d\u5b89\u88c5\u6784\u5efa\u7684\u9700\u6c42\uff0c\n\u4e4b\u540e\u624d\u4f1a\u542f\u52a8\u8f6f\u4ef6\u5305\u7684\u6784\u5efa\u8fc7\u7a0b\u3002</p><p>\u5982\u679c\u4f60\u4e0d\u5e0c\u671b\u4f7f\u7528\u6784\u5efa\u9694\u79bb\uff08\u901a\u5e38\u662f\u6307\u53ef\u7f16\u8f91\u6a21\u5f0f\u7684\u5b89\u88c5\uff09\uff0c\u53ef\u4ee5\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span> <span class=\"pre\">install</span></code>\n\u547d\u4ee4\u6307\u5b9a <code class=\"docutils literal notranslate\"><span class=\"pre\">--no-build-isolation</span></code> \u53c2\u6570\u3002\u8bbe\u7f6e\u8fd9\u4e00\u53c2\u6570\u4e4b\u540e\uff0c\u5b89\u88c5\u7a0b\u5e8f\u4f1a\u5728\u8bc6\u522b\u51fa\u4f9d\u8d56\u9879\u540e\uff0c\n\u5c3d\u53ef\u80fd\u590d\u7528\u7cfb\u7edf\u4e0a\u5df2\u7ecf\u5b89\u88c5\u4e86\u7684\u3001\u7248\u672c\u517c\u5bb9\u7684\u8f6f\u4ef6\u5305\u3002\n\u8fd9\u4e5f\u610f\u5473\u7740\u4f5c\u4e3a\u7528\u6237\u7684\u4f60\u8981\u5728\u81ea\u5df1\u7684\u73af\u5883\u4e2d\u9884\u5148\u5b89\u88c5 <code class=\"docutils literal notranslate\"><span class=\"pre\">build-requirements</span></code> \u7684\u5185\u5bb9\u3002\n\u5982\u679c\u4e0d\u542f\u7528\u6784\u5efa\u9694\u79bb\uff0c\u4f60\u9700\u8981\u67e5\u9605 <code class=\"docutils literal notranslate\"><span class=\"pre\">pyproject.toml</span></code> \u6587\u4ef6\u4e2d\u7684 <code class=\"docutils literal notranslate\"><span class=\"pre\">[build-system.requires]</span></code>\n\u5c0f\u8282\uff0c\u624b\u52a8\u5b89\u88c5\u5176\u4e2d\u5217\u4e3e\u7684\u8f6f\u4ef6\u5305\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
